        cb = np.array(b, dtype=object)
        c = np.convolve(ca, cb)
        # c is object array
        return [int(x % p) for x in c]
    except Exception:
        # pure python
        n = len(a); m=len(b)
        res=[0]*(n+m-1)
        for i, av in enumerate(a):
            if av==0:
                continue
            for j, bv in enumerate(b):
