    for(int i=0;i<n;i++) out[i]=0;
    for(int i=0;i<na;i++) if(a[i]!=0) {
        for(int j=0;j<nb;j++) if(b[j]!=0) {
            out[i+j] = (out[i+j] + a[i]*b[j]) % p;
        }
    }
}
'''
    open("/tmp/conv.c","w").write(code)
    print("gcc exists:", shutil.which("gcc"))
    r=subprocess.run(["gcc","-O2","-shared","-fPIC","/tmp/conv.c","-o","/tmp/conv.so"], capture_output=True, text=True)
    print("compile rc", r.returncode)
    print("stdout", r.stdout)
    print("stderr", r.stderr)
    print("exists", os.path.exists("/tmp/conv.so"))
    assert r.returncode==0
    lib=ctypes.CDLL("/tmp/conv.so")
    lib.conv_mod.argtypes=[ctypes.POINTER(ctypes.c_int64), ctypes.c_int, ctypes.POINTER(ctypes.c_int64), ctypes.c_int, ctypes.c_int64, ctypes.POINTER(ctypes.c_int64)]
    lib.conv_mod.restype=None
